module counter4(input logic clk, rst, output logic [3:0] q);
    // Initialize the counter to 0
    logic [3:0] counter = 4'b0000;

    // Reset the counter to 0 on the rising edge of the reset signal
    always @(posedge rst or negedge clk) begin
        if (rst) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1'b1;
        end
    end

    // Output the current value of the counter
    always @(*) begin
        q <= counter;
    end
endmodule

